	public List<Perso> fillOtpremnice(String fileImportName, String user) {
		logger.info("***********************BEGIN fillOtpremnice***********************");
		List<Perso> persoList = new ArrayList<>();
		List<Perso> persoExportedDatabase = persoRepo.findByfileImportNameAndStatus(fileImportName, statusExported);
		LocalDateTime currentDateAndTime = LocalDateTime.now();
		logger.info("***********************persoExportedDatabase size*********************** {}", persoExportedDatabase.size());
		for (Perso perso : persoExportedDatabase) {
			if (perso.getPackagedef().equalsIgnoreCase("000"))
				perso.setOPaket("Redovna");
			else
				perso.setOPaket("Obnova");
			if (!perso.getDeliverymethode().equalsIgnoreCase("br") && !perso.getDeliverymethode().equalsIgnoreCase("ex"))
				perso.setOBranch("XXXX");
			else
				perso.setOBranch(perso.getBranchExport());
			if (perso.getDeliverymethode().equalsIgnoreCase("br") || perso.getDeliverymethode().equalsIgnoreCase("ex"))
				perso.setOPxcode(null);
			else
				perso.setOPxcode(perso.getEan());
			perso.setOStatus(status_Otp_opened);
			perso.setODatum(currentDateAndTime);
			perso.setOStampa(CS.NOT_PRINTED.getId());
			perso.setNotifSentFlag(0);
			persoList.add(perso);
			persoRepo.save(perso);
			
		}

		logger.info("***********************BEGIN LOGING after fillOtpremnice***********************");
		logger.info("***********************persoExportedDatabase.size()*********************** {}", persoList.size());
		if (persoList.size() > 0)
			persoHistoryService.saveLog(persoList.get(0), currentDateAndTime,
					persoList.get(0).getODatum(), user, "SendToProduction"); // sacuva prvi
		
		return persoList;
	}

