	private static final Pattern PX_PATTERN = Pattern.compile("^[a-zA-Z0-9]{1,20}$");

	/*
	 * Metoda za unos px coda
	 */
	public List<Perso> fillPxCodeOtpremnice(String branch, String px, String user) {
		logger.info("BEGIN fillPxCodeOtpremnice");

		if (px == null || px.trim().isEmpty()) {
			logger.info("Prazan PX kod â€” preskaÄem update.");
			return Collections.emptyList();
		}

		if (!PX_PATTERN.matcher(px).matches()) {
			logger.warn("Nevalidan PX kod: {}", px);
			throw new IllegalArgumentException("PX kod moÅ¾e sadrÅ¾ati samo velika slova i brojeve, maksimalno 20 karaktera.");
		}

		List<Perso> otvoreneOtpremnice = persoRepo.findByOBranchAndOStatusOrderByOBranchAsc(branch, status_Otp_opened);
		LocalDateTime currentDateAndTime = LocalDateTime.now();

		otvoreneOtpremnice.forEach(o -> {
			o.setOPxcode(px);
			o.setODatum(currentDateAndTime);
		});

		otvoreneOtpremnice.forEach(persoRepo::save);

		if (!otvoreneOtpremnice.isEmpty()) {
			persoHistoryService.saveLog(
					otvoreneOtpremnice.get(0),
					currentDateAndTime,
					otvoreneOtpremnice.get(0).getODatum(),
					user,
					"UpdatePXCode"
			);
		}

		return otvoreneOtpremnice;
	}

