	public void maskedCardNumber(Perso perso) {
		String cardNumber = perso.getCardNumber();
		if (cardNumber == null) {
			return;
		}
		cardNumber = cardNumber.trim();
		if (cardNumber.length() != 16) {
			return;
		}
		String first4 = cardNumber.substring(0, 4);
		String last4 = cardNumber.substring(12, 16);
		String maskedNumber = first4 + " **** **** " + last4;
		perso.setCardNumber(maskedNumber);
	}

