	public ResponseEntity<Boolean> importFiles(@RequestParam String user, HttpServletRequest sec_request) throws IOException, FileImportException {

		var timestamp = LocalDateTime.now().toString();
		var requestId = UUID.randomUUID().toString();

		logger.info("POZIV importFiles. requestId={} timestamp={}", requestId, timestamp);

		sec_logger.info(sec_request, OperationCategory.DATA_READ_MODIFY_DELETE, "Import all files. RequestID: " + requestId);

		String userName = jwtUtils.getUsername();
		List<PersoDTO> listaImportovanih = persoService.importPersosAndSave(userName);

		if (listaImportovanih != null && !listaImportovanih.isEmpty()) {
			logger.info("Uspesan importPersosAndSave. requestId={}", requestId);
			return ResponseEntity.ok(true);
		} else {
			logger.info("Prazna lista importovanih. requestId={}", requestId);
			return ResponseEntity.ok(false);
		}
	}

	@GetMapping("/exportFiles")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN')")
	public ResponseEntity<Map<String, Object>> writeFiles(@RequestParam String user, HttpServletRequest sec_request) throws IOException {
		var timestamp = LocalDateTime.now().toString();
		var requestId = UUID.randomUUID().toString();
		logger.info("POZIV exportFiles. requestId={} timestamp={} ", requestId, timestamp);
		sec_logger.info(sec_request, OperationCategory.DATA_READ_MODIFY_DELETE, "Export all files.");

		logger.info("***********************BEGIN EXPORT***********************");
		logger.info("Export started at {}", LocalDateTime.now());
		logger.info("workingExport {}", workingExport);

		if (workingExport) {
			Map<String, Object> response = new HashMap<>();
			response.put("status", "duplicate");
			response.put("message", "Export already in progress");
			return ResponseEntity.status(HttpStatus.CONFLICT).body(response);
		}

		workingExport = true;
		try {
			String userName = jwtUtils.getUsername();
			List<Perso> listaExportovanih = persoService.exportFiles(userName);

			if (listaExportovanih != null && !listaExportovanih.isEmpty()) {
				logger.info("Export success end at {}", LocalDateTime.now());
				Map<String, Object> response = new HashMap<>();
				response.put("status", "success");
				response.put("message", "Export completed");
				return ResponseEntity.ok(response);
			} else {
				logger.info("Export unsuccess end at {}", LocalDateTime.now());
				Map<String, Object> response = new HashMap<>();
				response.put("status", "empty");
				response.put("message", "No files to export");
				return ResponseEntity.ok(response);
			}

		} catch (Exception e) {
			logger.error("Export error", e);
			Map<String, Object> response = new HashMap<>();
			response.put("status", "error");
			response.put("message", "Export failed due to server error");
			return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(response);
		} finally {
			workingExport = false;
			logger.info("workingExport reset to false");
		}
	}

