	@GetMapping("/postaStampaXlsx")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN')")
	public ResponseEntity<Object> postaStampaXlsx (HttpServletResponse response, HttpServletRequest sec_request) throws IOException {
		sec_logger.info(sec_request, OperationCategory.DATA_READ_MODIFY_DELETE, "Print xlsx for POST office.");
		fileService.postaStampa();
		logger.info("postaStampaXlsx*******");

		LocalDateTime currentDateTime = LocalDateTime.now();
		DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy.MM.dd.HHmmss");
		String formattedDateTime = currentDateTime.format(formatter);
		String filename = "PostaStampa"+formattedDateTime+".xlsx";

//		String filename = "PostaDatum.xlsx";
		byte[] documentInBytes = fileService.postaStampaXlsx();

		response.setHeader("Content-Disposition", "inline; filename=" + filename);
		response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
		response.setContentLength(documentInBytes.length);

		try (ServletOutputStream outputStream = response.getOutputStream()) {
			outputStream.write(documentInBytes);
			outputStream.flush();
		} catch (Exception e) {
			logger.error("Greska pri pisanju XLSX stampa za postu.", e);
