	@Override
	public PersoHistory saveLog(Perso p, LocalDateTime vremePromenePerso,LocalDateTime vremePromeneOtp, String user, String action) {
		PersoHistory persoHistory = new PersoHistory();
		persoHistory.setFileExportName(p.getFileExportName());
		persoHistory.setFileExportTime(p.getFileExportTime());
		persoHistory.setFileImportName(p.getFileImportName());
		persoHistory.setFileImportTime(p.getFileImportTime());
		persoHistory.setStatus(p.getStatus());
		persoHistory.setUpdatedBy(user);
//		DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
//		String vremePromene_formatted = vremePromenePerso.format(formatter);
		persoHistory.setUpdatedAt(vremePromenePerso);
		/*Deo otpremnice*/
		persoHistory.setOPaket(p.getOPaket());
		persoHistory.setOStatus(p.getOStatus());
		persoHistory.setOBranch(p.getOBranch());
		persoHistory.setOPxcode(p.getOPxcode());
		persoHistory.setOUpdatedBy(user);
		persoHistory.setOUpdatedAt(vremePromeneOtp);
		persoHistory.setAction(action);

		persoHistoryRepo.save(persoHistory);
		return persoHistory;
	}


