	public List<PersoHistory> findByFileImportNameAndClient(String fileName,String clientNumber, Integer persoId) {
		
		List <PersoHistory> phList = persoHistoryRepo.findByFileImportNameAndClient(fileName,clientNumber);
		List <CardRegistrationHistory> crhList = crhr.findAllByPersoIdOrderByUpdatedAtDesc(persoId);
		for (CardRegistrationHistory cardRegistrationHistory : crhList) {
			PersoHistory ph = new PersoHistory();
			ph.setAction(cardRegistrationHistory.getStatusDescription());
			ph.setUpdatedAt(cardRegistrationHistory.getUpdatedAt());
			ph.setUpdatedBy(cardRegistrationHistory.getUpdatedBy());
			phList.add(0, ph);
		}
//		Set<String> actionsToRemove = Set.of( "Proizvodnja", "SendToProduction", "SlanjePaketa", "UpdatePXCode", "VracanjeOtpremnice", "StampaOtpremnica" );
		Set<String> actionsToRemove = Set.of( "Proizvodnja", "UpdatePXCode", "StampaOtpremnica" );
		phList.removeIf(obj -> actionsToRemove.contains(obj.getAction()));

		phList.sort(Comparator.comparing(PersoHistory::getUpdatedAt).reversed());
		return phList;
	}

